sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-cap {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  overflow: hidden;
}

/* ---------- headline ---------- */

.wrm-cap-top { padding: 16px 18px 14px; }
.wrm-cap-top .line { font-size: 16px; color: var(--ink); line-height: 1.5; }
.wrm-cap-top .line strong { font-weight: 500; }

.wrm-cap-top .meta {
  display: flex; align-items: baseline; gap: 10px;
  flex-wrap: wrap; margin-top: 5px;
}
.wrm-cap-top .sub { font-size: 13px; color: var(--ink-3); }
.wrm-cap-top .toggle {
  margin-left: auto;
  background: none; border: 0; padding: 0;
  font-size: 12px; color: var(--clay); cursor: pointer;
}
.wrm-cap-top .toggle:hover { text-decoration: underline; }

/* ---------- type breakdown ---------- */

.wrm-cap-types { border-top: 1px solid var(--line); padding: 6px 18px 12px; }

.wrm-cap-types .row {
  display: flex; align-items: center; gap: 12px;
  padding: 7px 0;
  border-top: 1px solid var(--line);
}
.wrm-cap-types .row:first-child { border-top: 0; }

.wrm-cap-types .nm { width: 130px; flex: none; font-size: 12px; color: var(--ink); }
.wrm-cap-types .ct { flex: none; font-size: 11px; color: var(--ink-3); }

.wrm-cap-types .dots { display: flex; gap: 5px; flex: 1; flex-wrap: wrap; }
.wrm-cap-types .dots i { width: 10px; height: 10px; border-radius: 50%; display: block; }
.wrm-cap-types .dots i.free   { background: var(--free-fg); opacity: .55; }
.wrm-cap-types .dots i.booked { background: var(--held-fg); opacity: .45; }
.wrm-cap-types .dots i.maint  { background: var(--out-fg);  opacity: .45; }

.wrm-cap-types .key {
  display: flex; gap: 16px;
  margin-top: 10px; padding-top: 11px;
  border-top: 1px solid var(--line);
  font-size: 11px; color: var(--ink-3);
}
.wrm-cap-types .key i {
  display: inline-block; width: 9px; height: 9px;
  border-radius: 50%; margin-right: 5px;
}
.wrm-cap-types .key i.free   { background: var(--free-fg); opacity: .55; }
.wrm-cap-types .key i.booked { background: var(--held-fg); opacity: .45; }
.wrm-cap-types .key i.maint  { background: var(--out-fg);  opacity: .45; }

/* ---------- pulse ---------- */

.wrm-cap-pulse { border-top: 1px solid var(--line); padding: 14px 18px 16px; }

.wrm-cap-pulse .phead {
  display: flex; align-items: baseline; gap: 12px;
  flex-wrap: wrap; margin-bottom: 11px;
}
.wrm-cap-pulse .pline { font-size: 13px; color: var(--ink); }
.wrm-cap-pulse .pkey { font-size: 11px; color: var(--ink-3); margin-left: auto; }

.wrm-cap-pulse .bars {
  display: grid; grid-template-columns: repeat(10, 1fr);
  gap: 6px; align-items: end; height: 50px;
}
.wrm-cap-pulse .bars .col { height: 100%; display: flex; align-items: flex-end; }
.wrm-cap-pulse .bars .bar {
  display: block; width: 100%;
  background: var(--free-fg); opacity: .32;
  border-radius: 3px 3px 0 0;
}
.wrm-cap-pulse .bars .bar.today { background: var(--clay); opacity: .6; }

.wrm-cap-pulse .labels {
  display: grid; grid-template-columns: repeat(10, 1fr);
  gap: 6px; margin-top: 6px;
}
.wrm-cap-pulse .labels .col { text-align: center; }
.wrm-cap-pulse .labels .wd { display: block; font-size: 9px; letter-spacing: .06em; color: var(--ink-3); }
.wrm-cap-pulse .labels .dn { display: block; font-size: 10px; color: var(--ink-3); }
.wrm-cap-pulse .labels .col.today .wd,
.wrm-cap-pulse .labels .col.today .dn { color: var(--clay); }

sp_widget.script:
(function() {

  var WEEKDAYS_FULL = { MON:'Monday', TUE:'Tuesday', WED:'Wednesday',
                        THU:'Thursday', FRI:'Friday' };
  var WEEKDAYS = ['SUN','MON','TUE','WED','THU','FRI','SAT'];
  var HOLDING  = 'pending_check_in,checked_in';

  var todayYmd = new GlideDateTime().getDisplayValue().split(' ')[0];
  var tp = todayYmd.split('-');
  var todayUtc = Date.UTC(+tp[0], +tp[1] - 1, +tp[2]);

  function ymd(ms) {
    var d = new Date(ms);
    var m = d.getUTCMonth() + 1;
    var day = d.getUTCDate();
    return d.getUTCFullYear() + '-' +
           (m < 10 ? '0' + m : m) + '-' +
           (day < 10 ? '0' + day : day);
  }

  // --- 1. The next ten weekdays ---
  var days = [];
  var cursor = todayUtc;
  while (days.length < 10) {
    var d = new Date(cursor);
    var dow = d.getUTCDay();
    if (dow !== 0 && dow !== 6) {
      days.push({
        ymd:     ymd(cursor),
        weekday: WEEKDAYS[dow],
        dayNum:  ('0' + d.getUTCDate()).slice(-2),
        isToday: ymd(cursor) === todayYmd,
        booked:  0
      });
    }
    cursor += 86400000;
  }

  var firstYmd = days[0].ymd;
  var lastYmd  = days[days.length - 1].ymd;

  // --- 2. Reservations touching those days, and today's holds ---
  var heldToday = {};

  var res = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  res.addQuery('reservation_status', 'IN', HOLDING);
  res.query();

  while (res.next()) {
    var sDisp = res.getDisplayValue('work_start');
    var eDisp = res.getDisplayValue('work_end');
    if (!sDisp || !eDisp) continue;

    var sYmd = sDisp.split(' ')[0];
    var eYmd = eDisp.split(' ')[0];

    if (sYmd <= todayYmd && eYmd >= todayYmd) {
      heldToday[res.getValue('workspace')] = true;
    }

    if (eYmd < firstYmd || sYmd > lastYmd) continue;
    for (var i = 0; i < days.length; i++) {
      if (sYmd <= days[i].ymd && eYmd >= days[i].ymd) {
        days[i].booked++;
      }
    }
  }

  // --- 3. Group today's spaces by type ---
  var types = {};
  var maintCount = 0;
  var bookable = 0;

  var gr = new GlideRecord('x_1903615_worksp_0_workspace_options');
  gr.addQuery('status', '!=', 'decommissioned');
  gr.orderBy('workspace_name');
  gr.query();

  while (gr.next()) {
    var label = gr.getDisplayValue('workspace_type') || 'Other';
    if (!types[label]) {
      types[label] = { name: label, total: 0, free: 0, dots: [] };
    }

    var state;
    if (gr.getValue('status') === 'under_maintenance') {
      state = 'maint';
      maintCount++;
    } else {
      bookable++;
      if (heldToday[gr.getUniqueValue()]) {
        state = 'booked';
      } else {
        state = 'free';
        types[label].free++;
      }
    }

    types[label].total++;
    types[label].dots.push(state);
  }

  var ORDER = { free: 0, booked: 1, maint: 2 };

  data.types = [];
  var best = null;
  var fullTypes = [];

  for (var k in types) {
    var row = types[k];
    row.dots.sort(function(a, c) { return ORDER[a] - ORDER[c]; });
    data.types.push(row);
    if (!best || row.free > best.free) best = row;
    if (row.free === 0) fullTypes.push(row.name);
  }

  data.types.sort(function(a, c) { return c.free - a.free; });

  data.headline = '';
  if (best && best.free > 0) {
    data.headline      = best.name;
    data.headlineFree  = best.free;
    data.headlineTotal = best.total;
  }

  var bits = [];
  if (fullTypes.length === 1) {
    bits.push('No ' + fullTypes[0].toLowerCase() + ' is free today.');
  } else if (fullTypes.length > 1) {
    bits.push(fullTypes.length + ' types are fully booked.');
  }
  if (maintCount === 1) {
    bits.push('One space is out for maintenance.');
  } else if (maintCount > 1) {
    bits.push(maintCount + ' spaces are out for maintenance.');
  }
  data.detail = bits.join(' ');

  // --- 4. The pulse ---
  // Bars scale against total bookable capacity, not against the
  // busiest day. Scaling to peak makes a single reservation look
  // like a full office.
  if (bookable < 1) bookable = 1;

  var peak = 0;
  var quietest = null;

  for (var j = 0; j < days.length; j++) {
    days[j].occupancy = Math.round((days[j].booked / bookable) * 100);
    days[j].pct = days[j].occupancy;
    if (days[j].pct < 4) days[j].pct = 4;   // a visible stub

    if (days[j].booked > peak) peak = days[j].booked;
    if (!quietest || days[j].booked < quietest.booked) quietest = days[j];
  }

  data.days = days;

  // If almost nothing is booked, naming a "quietest day" is noise.
  var peakPct = Math.round((peak / bookable) * 100);
  if (peakPct < 15) {
    data.pulseLine = 'The office is quiet for the next two weeks.';
  } else {
    data.pulseLine = (WEEKDAYS_FULL[quietest.weekday] || quietest.weekday) +
                     ' ' + parseInt(quietest.dayNum, 10) +
                     ' is the quietest day coming up.';
  }

})();
